import { NativeTabs } from "expo-router/native-tabs";
import { useColors } from "@/lib/ui";

// iOS tab bar: the native UITabBar, which iOS 26 and later draw in Liquid Glass over the content.
// The web dashboard keeps the JS tabs in _layout.tsx, so keep both tab lists in step.
const TABS = [
  { name: "index", label: "Map", icon: "map", selectedIcon: "map.fill" },
  { name: "night", label: "Night", icon: "moon.zzz", selectedIcon: "moon.zzz.fill" },
  { name: "stays", label: "Stays", icon: "bed.double", selectedIcon: "bed.double.fill" },
  {
    name: "account",
    label: "Account",
    icon: "person.crop.circle",
    selectedIcon: "person.crop.circle.fill",
  },
] as const;

export default function TabsLayout() {
  const colors = useColors();
  return (
    <NativeTabs tintColor={colors.accent}>
      {TABS.map((tab) => (
        <NativeTabs.Trigger key={tab.name} name={tab.name}>
          <NativeTabs.Trigger.Label>{tab.label}</NativeTabs.Trigger.Label>
          <NativeTabs.Trigger.Icon sf={{ default: tab.icon, selected: tab.selectedIcon }} />
        </NativeTabs.Trigger>
      ))}
    </NativeTabs>
  );
}
import type { ReactNode } from "react";
import { Screen, Text } from "@/lib/ui";
import { LOADING } from "../copy";
import { useAccount } from "../hooks/useAccount";
import { Onboarding } from "./Onboarding";

/**
 * Shows onboarding until the user has made their consent choices, then `children`. Render it
 * inside the tRPC provider. If the account cannot load, `children` show with every consent off,
 * so nothing asks iOS for a permission.
 */
export function ConsentGate({ children }: { children: ReactNode }) {
  const account = useAccount();
  if (account.status === "loading") {
    return (
      <Screen>
        <Text variant="caption">{LOADING}</Text>
      </Screen>
    );
  }
  if (account.status === "onboarding") {
    return (
      <Screen>
        <Onboarding savedProfile={account.view.profile} />
      </Screen>
    );
  }
  return <>{children}</>;
}
